// ── Bóc tách bài viết & lọc bài viết trong 24h ──────────────────────────
const allInputs = $input.all();
let rawPosts = [];

for (const item of allInputs) {
  const data = item.json || {};
  if (Array.isArray(data)) {
    rawPosts.push(...data);
  } else if (Array.isArray(data.posts)) {
    rawPosts.push(...data.posts);
  } else if (data.message || data.text || data.postId || data.id) {
    rawPosts.push(data);
  }
}

const now = new Date();
const cutoff = new Date(now.getTime() - 24 * 60 * 60 * 1000);

const results = [];
const seenIds = new Set();

for (const post of rawPosts) {
  const msg = String(post.message || post.text || '').trim();
  if (!msg || msg.length < 10) continue;

  const pId = String(post.postId || post.post_id || post.id || `fb_${Date.now()}_${Math.random()}`);
  if (seenIds.has(pId)) continue;
  seenIds.add(pId);

  const postTime = post.created_time || post.createdAt || post.time;
  const parsedTime = postTime ? new Date(postTime) : null;
  if (parsedTime && !isNaN(parsedTime.getTime()) && parsedTime < cutoff) continue;

  results.push({
    post_id:      pId,
    author:       String(post.author || post.authorName || post.username || 'Người dùng Facebook'),
    message:      msg,
    permalink:    String(post.permalink || post.url || 'https://www.facebook.com'),
    created_time: postTime || now.toISOString()
  });
}

// Khi test trong n8n Editor hoặc khi Scraper chưa có bài mới -> Tự động nạp Lead mẫu để test
if (results.length === 0 && ($execution?.mode === 'test' || $execution?.mode === 'manual' || $input.first()?.json?.__testTrigger)) {
  results.push({
    post_id:      `test_lead_${Date.now()}`,
    author:       'Khách Hàng Test (Demo Lead)',
    message:      'Mình cần tìm team thiết kế website bán hàng thương mại điện tử chuyên nghiệp chuẩn SEO, tích hợp chatbot AI tư vấn và cổng thanh toán tự động. Ngân sách tầm 15 - 25 triệu, ai làm được inbox mình nhé.',
    permalink:    'https://www.facebook.com/groups/1998083910206781/posts/demo_lead',
    created_time: now.toISOString()
  });
}

return results.map(p => ({ json: p }));

// ── Chuẩn bị dữ liệu Lead và mẫu comment chào hàng chuyên nghiệp ────────────────
const matchedPosts = $input.all();
const professionalComment = 'Chào bạn, bên mình chuyên thiết kế & phát triển Website/Web App theo yêu cầu (UI/UX độc quyền, chuẩn SEO Google, tốc độ tải cực nhanh, bàn giao 100% mã nguồn & bảo hành kỹ thuật 12 tháng).\n\n📁 Portfolio dự án: company-plum-rho . vercel . app (bỏ dấu cách)\n📞 Hotline/Zalo tư vấn: 0845.663.357\n\nBạn check inbox hoặc kết bạn Zalo để bên mình gửi bản demo giao diện và bảng báo giá chi tiết nhé!';

const results = [];
for (let i = 0; i < matchedPosts.length; i++) {
  const post = matchedPosts[i]?.json || {};

  results.push({
    json: {
      post_id:       post.post_id || `lead_${Date.now()}_${i}`,
      author:        post.author || 'Người dùng Facebook',
      message:       post.message || '',
      permalink:     post.permalink || 'https://www.facebook.com',
      created_time:  post.created_time || new Date().toISOString(),
      ai_comment:    professionalComment,
      lead_score:    10,
      score_reason:  'Bài viết khớp từ khóa tìm kiếm dịch vụ website / digital',
      score_badge:   '🔥'
    }
  });
}

return results;

// ── Chỉ giữ lại các Lead THỰC SỰ MỚI (được INSERT thành công vào DB) ────────
const items = $input.all();
const newLeads = [];

for (const item of items) {
  const data = item.json || {};
  // Khi ON CONFLICT DO NOTHING xảy ra, Postgres trả về { success: true } và KHÔNG có data.id / data.post_id
  if (data.id && data.post_id && data.permalink) {
    newLeads.push(item);
  }
}

return newLeads;

// ── Merge kết quả comment với dữ liệu Lead ──────────────────────────────
const commentOutputs = $input.all();
const preparedLeads = $('Filter New Leads Only').all();

return commentOutputs.map((item, idx) => {
  const lead = preparedLeads[idx]?.json || {};
  const commentRes = item.json || {};
  let errorMsg = '';
  if (commentRes.error) {
    errorMsg = typeof commentRes.error === 'object' ? (commentRes.error.message || JSON.stringify(commentRes.error)) : String(commentRes.error);
  } else if (commentRes.message && !commentRes.success) {
    errorMsg = String(commentRes.message);
  }

  let botStatus = '✅ Đã tự động post comment';
  if (commentRes.alreadyCommented) {
    botStatus = 'ℹ️ Bài viết đã có bình luận từ trước (Bỏ qua)';
  } else if (!commentRes.success) {
    botStatus = '⚠️ ' + (errorMsg || 'Chưa tự động comment được');
  }

  return {
    json: {
      ...lead,
      comment_success: Boolean(commentRes.success),
      already_commented: Boolean(commentRes.alreadyCommented),
      bot_status_text: botStatus
    }
  };
});

